import { concatHex, encodeAbiParameters, keccak256 } from 'viem';
import { RPCAppStateIntent } from './types.js';
const WALLET_QUORUM_PREFIX = '0xa1';
const SESSION_KEY_QUORUM_PREFIX = '0xa2';
const RAW_WALLET_SIGNATURE_LENGTH = 132;
const WRAPPED_WALLET_SIGNATURE_LENGTH = 134;
function normalizeIntent(intent) {
    if (typeof intent === 'number')
        return intent;
    switch (intent) {
        case RPCAppStateIntent.Operate:
            return 0;
        case RPCAppStateIntent.Deposit:
            return 1;
        case RPCAppStateIntent.Withdraw:
            return 2;
        case 'close':
            return 3;
        default:
            throw new Error(`Unsupported app state intent: ${intent}`);
    }
}
export function packCreateAppSessionHash(params) {
    return keccak256(encodeAbiParameters([
        { type: 'string' },
        {
            type: 'tuple[]',
            components: [
                { name: 'walletAddress', type: 'address' },
                { name: 'signatureWeight', type: 'uint8' },
            ],
        },
        { type: 'uint8' },
        { type: 'uint64' },
        { type: 'string' },
    ], [
        params.application,
        params.participants.map((participant) => ({
            walletAddress: participant.walletAddress,
            signatureWeight: participant.signatureWeight,
        })),
        params.quorum,
        BigInt(params.nonce),
        params.sessionData ?? '',
    ]));
}
export function packSubmitAppStateHash(params) {
    return keccak256(encodeAbiParameters([
        { type: 'bytes32' },
        { type: 'uint8' },
        { type: 'uint64' },
        {
            type: 'tuple[]',
            components: [
                { name: 'participant', type: 'address' },
                { name: 'asset', type: 'string' },
                { name: 'amount', type: 'string' },
            ],
        },
        { type: 'string' },
    ], [
        params.appSessionId,
        normalizeIntent(params.intent),
        BigInt(params.version),
        params.allocations.map((allocation) => ({
            participant: allocation.participant,
            asset: allocation.asset,
            amount: allocation.amount,
        })),
        params.sessionData ?? '',
    ]));
}
export function toWalletQuorumSignature(signature) {
    const normalized = signature.toLowerCase();
    if (!normalized.startsWith('0x')) {
        throw new Error('Signature must be a hex string with 0x prefix');
    }
    if (normalized.startsWith(WALLET_QUORUM_PREFIX) &&
        normalized.length === WRAPPED_WALLET_SIGNATURE_LENGTH) {
        return normalized;
    }
    if (normalized.length !== RAW_WALLET_SIGNATURE_LENGTH) {
        throw new Error('Expected a 65-byte wallet signature (0x + 130 hex chars)');
    }
    return concatHex([WALLET_QUORUM_PREFIX, normalized]);
}
export function toSessionKeyQuorumSignature(signature) {
    const normalized = signature.toLowerCase();
    if (!normalized.startsWith('0x')) {
        throw new Error('Signature must be a hex string with 0x prefix');
    }
    if (normalized.startsWith(SESSION_KEY_QUORUM_PREFIX) &&
        normalized.length === WRAPPED_WALLET_SIGNATURE_LENGTH) {
        return normalized;
    }
    if (normalized.length !== RAW_WALLET_SIGNATURE_LENGTH) {
        throw new Error('Expected a 65-byte session key signature (0x + 130 hex chars)');
    }
    return concatHex([SESSION_KEY_QUORUM_PREFIX, normalized]);
}
